const blocked = new Set();
const counts = new Map();   // ip -> requests this minute

function ddosGuard(req, res, next) {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  if (blocked.has(ip)) { res.status(403).end(); return; }

  const n = (counts.get(ip) || 0) + 1;
  counts.set(ip, n);
  if (n > 100) blocked.add(ip);   // permanent block

  next();   // do the full request work
}
